      const ends   = (d.requests || []).map(r => r.ended_at   ? Date.parse(r.ended_at)   : NaN).filter(t => !isNaN(t));
      const wall = (starts.length && ends.length) ? ((Math.max(...ends) - Math.min(...starts)) / 1000).toFixed(1) + "s" : "—";
      const optimize = d.optimize || [];
